CREATE TABLE IF NOT EXISTS airports (icao TEXT PRIMARY KEY, iata TEXT NOT NULL, name TEXT NOT NULL, city TEXT NOT NULL, countryCode TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, elevationFt INTEGER NOT NULL, timezone TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS aircraft (icao24 TEXT PRIMARY KEY, registration TEXT, aircraftType TEXT, manufacturer TEXT, operator TEXT, lastSeen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, region TEXT NOT NULL, observedAt INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS snapshot_region_time ON snapshots(region,observedAt);
CREATE TABLE IF NOT EXISTS aircraft_positions (id INTEGER PRIMARY KEY AUTOINCREMENT, snapshotId INTEGER NOT NULL, icao24 TEXT NOT NULL, callsign TEXT, latitude REAL NOT NULL, longitude REAL NOT NULL, altitudeM REAL, groundSpeedMs REAL, headingDeg REAL, verticalRateMs REAL, onGround INTEGER NOT NULL, observedAt INTEGER NOT NULL, ingestedAt INTEGER NOT NULL, source TEXT NOT NULL, data TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS position_snapshot_aircraft ON aircraft_positions(snapshotId,icao24);
CREATE INDEX IF NOT EXISTS position_aircraft_time ON aircraft_positions(icao24,observedAt);
CREATE INDEX IF NOT EXISTS position_time ON aircraft_positions(observedAt);
CREATE TABLE IF NOT EXISTS flights (id TEXT PRIMARY KEY, flightNumber TEXT NOT NULL, callsign TEXT, operatingAirline TEXT, originIcao TEXT NOT NULL, destinationIcao TEXT NOT NULL, aircraftIcao24 TEXT, scheduledDeparture INTEGER NOT NULL, scheduledArrival INTEGER NOT NULL, actualDeparture INTEGER, actualArrival INTEGER, estimatedArrival INTEGER, status TEXT NOT NULL, source TEXT NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS flight_route ON flights(originIcao,destinationIcao);
CREATE INDEX IF NOT EXISTS flight_schedule ON flights(scheduledDeparture);
CREATE TABLE IF NOT EXISTS airport_weather (id INTEGER PRIMARY KEY AUTOINCREMENT, airportIcao TEXT NOT NULL, validAt TEXT NOT NULL, temperatureC REAL, windSpeedMs REAL, windDirection REAL, windGustMs REAL, precipitationMm REAL, visibilityM REAL, cloudCoverPct REAL, pressureHpa REAL, forecastIssuedAt INTEGER, forecastRetrievedAt INTEGER NOT NULL, ingestedAt INTEGER NOT NULL, source TEXT NOT NULL, data TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS weather_airport_valid_issued ON airport_weather(airportIcao,validAt,forecastRetrievedAt);
CREATE INDEX IF NOT EXISTS weather_airport_time ON airport_weather(airportIcao,validAt);
CREATE TABLE IF NOT EXISTS predictions (id INTEGER PRIMARY KEY AUTOINCREMENT, flightId TEXT, modelVersion TEXT NOT NULL, predictedAt INTEGER NOT NULL, probability30 REAL NOT NULL, probability60 REAL NOT NULL, probability180 REAL NOT NULL, expectedDelayMin REAL, featureSnapshotJson TEXT NOT NULL, sourceDataTimestamp INTEGER);
CREATE TABLE IF NOT EXISTS compensation_assessments (id INTEGER PRIMARY KEY AUTOINCREMENT, flightId TEXT, assessedAt INTEGER NOT NULL, regulationVersion TEXT NOT NULL, eligibilityStatus TEXT NOT NULL, potentialAmountEur INTEGER NOT NULL, knownDisruptionCause TEXT NOT NULL, missingEvidenceJson TEXT NOT NULL, explanation TEXT NOT NULL, inputJson TEXT NOT NULL, resultJson TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notams (id TEXT PRIMARY KEY, notamNumber TEXT NOT NULL, airportIcao TEXT NOT NULL, rawText TEXT NOT NULL, category TEXT NOT NULL, effectiveStart INTEGER NOT NULL, effectiveEnd INTEGER, fetchedAt INTEGER NOT NULL, source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watchlists (id INTEGER PRIMARY KEY AUTOINCREMENT, targetType TEXT NOT NULL, targetId TEXT NOT NULL, settings TEXT NOT NULL DEFAULT '{}', createdAt INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS watchlist_target ON watchlists(targetType,targetId);
CREATE TABLE IF NOT EXISTS alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, watchlistId INTEGER NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, eventTimestamp INTEGER NOT NULL, acknowledgedAt INTEGER);
CREATE INDEX IF NOT EXISTS alert_watchlist_time ON alerts(watchlistId,eventTimestamp);
CREATE TABLE IF NOT EXISTS ingestion_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, startedAt INTEGER NOT NULL, completedAt INTEGER, status TEXT NOT NULL, recordCount INTEGER NOT NULL DEFAULT 0, errorSummary TEXT);
CREATE TABLE IF NOT EXISTS data_sources (id TEXT PRIMARY KEY, providerName TEXT NOT NULL, sourceType TEXT NOT NULL, lastSuccessAt INTEGER, accessStatus TEXT NOT NULL, message TEXT);
CREATE TABLE IF NOT EXISTS provider_cache (key TEXT PRIMARY KEY, value TEXT NOT NULL, expiresAt INTEGER NOT NULL);
